export interface Message { name: string, email: string, message: string }
export type MessageErrors = Partial<Record<keyof Message, string>>

export function checkMessage(input: Message): MessageErrors {
  const errors: MessageErrors = {}

  if (input.name.trim() === '')
    errors.name = 'Name is required.'

  const email = input.email.trim()
  if (email === '')
    errors.email = 'Email is required.'
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
    errors.email = 'Enter a valid email address.'

  if (input.message.trim().length < 20)
    errors.message = 'Message must be at least 20 characters.'

  return errors
}
